values.value:
{
  "fields": [
    {
      "apiName": "transportation_as",
      "label": "Transportation as",
      "type": "picklist",
      "required": true,
      "options": [
        "Lump sum",
        "Per pole/Mast"
      ],
      "controllingField": "freight_incoterms",
      "controllingValues": [
        "F.O.R (Freight on Road)"
      ]
    },
    {
      "apiName": "transportation_charges",
      "label": "Transportation Charges",
      "type": "number",
      "required": true,
      "controllingField": "transportation_as",
      "controllingValues": [
        "Lump sum",
        "Per pole/Mast"
      ]
    },
    {
      "apiName": "customer_address_override",
      "label": "Customer Address Override",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "freight_incoterms",
      "controllingValues": [
        "Ex-works",
        "F.O.R (Freight on Road)"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "CUSTOMER ADDRESS DETAILS",
          "modalFields": [
            {
              "id": "shipping_address",
              "label": "Shipping Address",
              "expanded": true,
              "fields": [
                {
                  "apiName": "def_street",
                  "label": "STREET",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@ShippingStreet@@"
                },
                {
                  "apiName": "def_city",
                  "label": "CITY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@ShippingCity@@"
                },
                {
                  "apiName": "def_zip",
                  "label": "ZIP-CODE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@ShippingPostalCode@@"
                },
                {
                  "apiName": "def_state",
                  "label": "STATE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@ShippingState@@"
                },
                {
                  "apiName": "def_country",
                  "label": "COUNTRY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@ShippingCountry@@"
                },
                {
                  "apiName": "def_phone",
                  "label": "PHONE NUMBER",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Phone@@"
                },
                {
                  "apiName": "override_existing_address",
                  "label": "OVERRIDE EXISTING ADDRESS?",
                  "type": "checkbox"
                }
              ]
            },
            {
              "id": "override_shipping_address",
              "label": "Override Shipping Address",
              "expanded": true,
              "controllingField": "override_existing_address",
              "controllingValues": [
                "true"
              ],
              "fields": [
                {
                  "apiName": "ovr_street",
                  "label": "STREET",
                  "type": "text"
                },
                {
                  "apiName": "ovr_city",
                  "label": "CITY",
                  "type": "text"
                },
                {
                  "apiName": "ovr_zip",
                  "label": "ZIP-CODE",
                  "type": "number"
                },
                {
                  "apiName": "ovr_state",
                  "label": "STATE",
                  "type": "text"
                },
                {
                  "apiName": "ovr_country",
                  "label": "COUNTRY",
                  "type": "text"
                },
                {
                  "apiName": "ovr_phone",
                  "label": "PHONE NUMBER",
                  "type": "number"
                }
              ]
            }
          ]
        }
      }
    },
    {
      "apiName": "terms_and_conditions",
      "label": "Terms & Conditions",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "freight_incoterms",
      "controllingValues": [
        "Ex-works",
        "F.O.R (Freight on Road)"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "TERMS & CONDITIONS",
          "modalFields": [
            {
              "id": "terms_and_conditions_details",
              "label": "Terms & Conditions Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_del_schedule",
                  "label": "Delivery Schedule",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 10
                },
                {
                  "apiName": "tc_del_schedule_in",
                  "label": "Delivery Schedule In",
                  "type": "picklist",
                  "colSpan": 4,
                  "options": [
                    "Days",
                    "Weeks",
                    "Months"
                  ],
 "defaultValue": "Days"
                },
                {
                  "apiName": "tc_price_variation",
                  "label": "Price Variation (Days)",
                  "type": "number",
"defaultValue": 30,
                  "colSpan": 4
                },
{
                  "apiName": "tc_quot_validity",
                  "label": "Quotation Validity (in days)",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 5
                },
                {
                  "apiName": "tc_comm_months",
                  "label": "Warranty From the date of Commissioning (in months)",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 12
                },
                {
                  "apiName": "tc_del_months",
                  "label": "Warranty From the Date of Delivery (in months)",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 18
                }
              ]
            }
          ]
        }
      }
    }
  ],
  "_lineItemAdjustments": [
    {
      "conditionField": "transportation_as",
      "conditionValue": "Per pole/Mast",
      "chargeField": "transportation_charges",
      "applyGST": false,
      "divideByQuantity": false,
      "targetItemNameIncludes": [
        "CUSTOM LIGHTNING MAST (5 SEGMENTS) - CLM - Segment",
        "LATCHING MAST (5 SEGMENTS) - LM - Segment",
        "SIGNAGE MAST - LM - Segment",
        "LIGHTNING CUM LIGHTING MAST - LM - Segment",
        "LIGHTING MAST (SEGMENT ABOVE 5) - LM - Segment",
        "STADIUM MAST - Segment Dimension",
        "FLAG MAST - FM - Segment",
        "LCLM - LM - Segment",
        "STANDARD LIGHTNING POLE - Segment",
        "CUSTOM LIGHTNING POLE - Segment",
        "MID HINGE POLE - Mid Hinge Pole Details",
        "LIGHTING MAST (5 SEGMENTS) - LM - Segment",
        "TRANSMISSION POLE - Segment",
        "STADIUM MAST - ESTIMATOR - Segment Dimension",
        "FLAG MAST - ESTIMATOR - FM - Segment"
      ],
      "applyTo": [
        "unitPrice",
        "unitCost"
      ]
    }
  ],
  "_newLineItemGenerators": [
    {
      "conditionField": "transportation_as",
      "conditionValue": "Lump sum",
      "chargeField": "transportation_charges",
      "applyGST": false,
      "itemName": "Transportation Charges (Lump Sum)",
      "applyTo": [
        "expenses"
      ]
    }
  ]
}
